  'f56e99a7-47f9-4242-86b4-3b9ff5f5f24a'::uuid, 'performance_indicator', 'Gestalt von Samenpflanzen kriteriengeleitet betrachten', 'die Gestalt von Samenpflanzen an Originalobjekten kriteriengeleitet betrachten (z. B. Ackersenf, Gartenerbse, Sonnenblume)',
  '5/6', 'Biologie', '{"id":"MNT-56-M2-FPA-1","thema":"2.2.7 Samenpflanzen","anmerkung":"Reale Pflanzen statt Abbildungen verwenden, wo verfügbar; eignet sich als direkter Einstieg in den Lernbereich","_source_id":"MNT-56-M2-FPA-1","unterthema":"Fachpraktische Arbeiten (Aufbau Samenpflanzen)","_source_file":"lernziele_MNT56.json","originaltext":"die Gestalt von Samenpflanzen an Originalobjekten kriteriengeleitet betrachten (z. B. Ackersenf, Gartenerbse, Sonnenblume)","bk_prinzipien":[],"ist_praktisch":true,"kognitionsverb":"betrachten_beschreiben","kurzbezeichnung":"Gestalt von Samenpflanzen kriteriengeleitet betrachten","abstraktionsgrad":"niedrig","ist_konzeptanker":false,"basiskonzeptbezug":[{"basiskonzept_id":"bk_struktur_funktion","begruendung":"Das kriteriengeleitete Vergleichen mehrerer Samenpflanzen an echten Exemplaren macht direkt sichtbar, dass sehr unterschiedlich aussehende Pflanzen (Ackersenf, Gartenerbse, Sonnenblume) denselben Grundaufbau aus Wurzel und Spross teilen. Das ist ein unmittelbarer Struktur-Funktion-Bezug: gleiche Bauplanelemente erfüllen bei jeder Art dieselben Grundfunktionen.","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Bauplan"],"relevante_unterkonzepte_taxonomie":[{"value":"Bauplan","taxonomyElementId":null}],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_evolutive_entwicklung","begruendung":"Dass so unterschiedlich wirkende Pflanzen einen gemeinsamen Grundbauplan teilen, ist ein früher, noch unausgesprochener Anknüpfungspunkt an gemeinsame Abstammung -- in dieser Lernbereichsphase wird das aber ausdrücklich noch nicht thematisiert, nur beobachtet.","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_individuelle_entwicklung","begruendung":"Das Betrachten ausgewachsener Exemp