uktur_funktion","begruendung":"Die unterschiedliche Oberflächenbeschaffenheit der getesteten Materialien (z. B. gewachst vs. unbehandelt) zeigt exemplarisch, wie eine Oberflächenstruktur eine bestimmte Funktion (wasserabweisend oder wasserliebend) hervorbringt -- ein Prinzip, das in der Biologie z. B. bei Laubblättern wiederkehrt.","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_steuerung_regelung","begruendung":"Ein Regelungsprozess ist hier nicht Gegenstand.","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]},{"basiskonzept_id":"bk_information_kommunikation","begruendung":"Informationsverarbeitung ist für dieses Experiment nicht relevant.","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte":[],"relevante_evolutionskonzepte_taxonomie":[]}],"unterthema_origin":"curriculum","empfohlenes_quartal":"Q2","systemebene_primaer":"Organismus","kognitive_anforderung":"anwendung","systemebene_sekundaer":null,"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Lernende testen Wassertropfenverhalten auf verschiedenen Materialien und protokollieren ihre Beobachtungen."},{"rang":2,"favorit":false,"methode":"Kooperative Lernformen","beschreibung":"Materialstationen werden arbeitsteilig in Kleingruppen untersucht und die Ergebnisse anschließend verglichen."}],"bezug_zum_lehrplan_kontext":"Praktische Umsetzung des Abschnitts \"Kohäsion, Adhäsion\".","moegliche_fehlvorstellungen":"Manche Lernende verwechseln zunächst Oberflächenspannung mit Oberflächenbeschaffenheit (z. B. Rauheit statt Benetzbarkeit).","e